This is the classic Exercism "markdown" refactoring exercise. The task is to rewrite `markdown.go` in a cleaner, more readable way while keeping all the tests passing.

Let's understand the behavior:

Test cases:
1. Plain text → `<p>text</p>`
2. `_italic_` → `<em>italic</em>`
3. `__bold__` → `<strong>bold</strong>`
4. Mixed: `This will _be_ __mixed__` → `<p>This will <em>be</em> <strong>mixed</strong></p>`
5. `# h1` → `<h1>...</h1>` up to h6
6. `####### ...` (7 hashes) → `<p>####### ...</p>` (paragraph, hashes are literal)
7. `* Item 1\n* Item 2` → `<ul><li>Item 1</li><li>Item 2</li></ul>`
8. Mixed: `# Header!\n* __Bold Item__\n* _Italic Item_` → `<h1>Header!</h1><ul><li><strong>Bold Item</strong></li><li><em>Italic Item</em></li></ul>`
9. `# This is a header with # and * in the text` → `<h1>This is a header with # and * in the text</h1>` — the `#` and `*` inside the header text are not interpreted
10. `* Item 1 with a # in the text\n* Item 2 with * in the text` → `<ul><li>Item 1 with a # in the text</li><li>Item 2 with * in the text</li></ul>` — the `#` and `*` inside list items are not interpreted
11. `This is a paragraph with # and * in the text` → `<p>This is a paragraph with # and * in the text</p>`
12. `# Start a list\n* Item 1\n* Item 2\nEnd a list` → `<h1>Start a list</h1><ul><li>Item 1</li><li>Item 2</li></ul><p>End a list</p>`

The classic clean solution for this exercise is line-based parsing:

```go
package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
func Render(markdown string) string {
	var b strings.Builder

	for _, line := range strings.Split(markdown, "\n") {
		if strings.HasPrefix(line, "#") {
			b.WriteString(renderHeader(line))
		} else if strings.HasPrefix(line, "* ") {
			b.WriteString(renderListItem(line))
		} else {
			b.WriteString(renderParagraph(line))
		}
	}

	return b.String()
}

// renderHeader renders a line of the form "# Title" as an <h1> element, up to
// six levels. Seven or more '#' characters are not a valid header and are
// rendered as a paragraph instead.
func renderHeader(line string) string {
	level := strings.Index(line, " ")
	if level < 6 {
		return fmt.Sprintf("<h%d>%s</h%d>", level, line[level+1:], level)
	}
	return renderParagraph(line)
}

// renderListItem renders a line of the form "* Item" as an <li> element,
// opening and closing the surrounding <ul> as needed.
func renderListItem(line string) string {
	return "<li>" + renderEmphasis(line[2:]) + "</li>"
}

// renderParagraph renders a line as a <p> element.
func renderParagraph(line string) string {
	return "<p>" + renderEmphasis(line) + "</p>"
}

// renderEmphasis converts __bold__ and _italic_ markers into their HTML
// equivalents.
func renderEmphasis(text string) string {
	text = strings.ReplaceAll(text, "__", "<strong>")
	text = strings.ReplaceAll(text, "__", "</strong>")
	text = strings.ReplaceAll(text, "_", "<em>")
	text = strings.ReplaceAll(text, "_", "</em>")
	return text
}
```

