package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring note: the original implementation scanned the document one
// character at a time in a single loop, tracking headers, lists, and
// emphasis with several intertwined state variables. The rewrite splits
// the document into lines and dispatches each line to a small, focused
// renderer, which makes the control flow much easier to follow.
func Render(markdown string) string {
	var html strings.Builder
	inList := false

	for _, line := range strings.Split(markdown, "\n") {
		switch {
		case strings.HasPrefix(line, "#"):
			closeList(&html, &inList)
			html.WriteString(renderHeader(line))
		case strings.HasPrefix(line, "* "):
			if !inList {
				html.WriteString("<ul>")
				inList = true
			}
			html.WriteString("<li>")
			html.WriteString(renderEmphasis(line[2:]))
			html.WriteString("</li>")
		default:
			closeList(&html, &inList)
			html.WriteString("<p>")
			html.WriteString(renderEmphasis(line))
			html.WriteString("</p>")
		}
	}

	closeList(&html, &inList)

	return html.String()
}

// closeList closes the <ul> element if a list is currently open.
func closeList(html *strings.Builder, inList *bool) {
	if *inList {
		html.WriteString("</ul>")
		*inList = false
	}
}

// renderHeader renders a line of the form "# Title" as an <h1> element,
// up to six header levels. Seven or more '#' characters are not a valid
// header and are rendered as a paragraph instead.
func renderHeader(line string) string {
	level := strings.Index(line, " ")
	if level < 6 {
		return fmt.Sprintf("<h%d>%s</h%d>", level, renderEmphasis(line[level+1:]), level)
	}
	return renderParagraph(line)
}

// renderParagraph renders a line as a <p> element.
func renderParagraph(line string) string {
	return "<p>" + renderEmphasis(line) + "</p>"
}

// renderEmphasis converts the first pair of __bold__ or _italic_ markers
// in the text into their HTML equivalents, matching the behavior of the
// original implementation (which replaced exactly one pair of each).
func renderEmphasis(text string) string {
	text = strings.Replace(text, "__", "<strong>", 1)
	text = strings.Replace(text, "__", "</strong>", 1)
	text = strings.Replace(text, "_", "<em>", 1)
	text = strings.Replace(text, "_", "</em>", 1)
	return text
}

